// fakeApi.ts
export type User = { id: number; name: string };

export const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

export async function fetchUser(id: number): Promise<User> {
  await wait(600);
  if (id === 0) throw new Error('Nie znaleziono użytkownika');
  return { id, name: ['Ala', 'Bob', 'Celina'][id % 3] };
}

export async function saveName(name: string): Promise<string> {
  await wait(800);
  if (name.trim().toLowerCase() === 'błąd') throw new Error('Serwer odrzucił imię');
  return name.trim();
}

