// EmailToggle.jsx
import { startTransition as startNested, useRef, useState, useTransition } from 'react';
import { wait } from './fakeApi';

export function EmailToggle() {
  const [enabled, setEnabled] = useState(true);
  const [error, setError] = useState(null);
  const [isPending, startTransition] = useTransition();
  const attempts = useRef(0);

  function handleToggle() {
    const next = !enabled;
    startTransition(async () => {
      setError(null);
      await wait(700);
      attempts.current += 1;
      if (attempts.current % 3 === 0) {
        startNested(() => setError('Nie udało się zapisać ustawienia'));
        return;
      }
      startNested(() => setEnabled(next));
    });
  }

  return (
    <div>
      <label>
        <input type="checkbox" checked={enabled} disabled={isPending} onChange={handleToggle} />
        Powiadomienia e-mail
      </label>
      {isPending && <small aria-live="polite">Zapisywanie…</small>}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}

