test("błąd zasobu ma działające ponowienie i nową granicę",async()=>{vi.spyOn(console,"error").mockImplementation(()=>{});const first=deferred<unknown>(),second=deferred<unknown>(),load=vi.fn().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);await act(async()=>{render(<UserExplorer load={load}/>);});await act(async()=>first.reject(Error("500")));expect(await screen.findByRole("alert")).toHaveTextContent("Nie udało");await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Ponów użytkownika"})));expect(screen.getByRole("status")).toHaveTextContent("Ładowanie");await act(async()=>second.resolve({id:1,name:"Ala"}));expect(await screen.findByText("Użytkownik: Ala")).toBeVisible();expect(load).toHaveBeenCalledTimes(2);});
