test("formularz łączy status rodzica, warstwę roboczą i potwierdzony wynik",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[])};render(<TrainingComments api={api} makeId={()=>"a"}/>);await submit();expect(screen.getByRole("listitem")).toHaveTextContent("wysyłanie");expect(screen.getByRole("button",{name:/Wysyłanie/})).toHaveAttribute("aria-busy","true");expect(screen.getByRole("button",{name:/Wysyłanie/})).toHaveTextContent("Mój komentarz");expect(screen.getByRole("textbox")).toBeDisabled();await act(async()=>task.resolve({id:"s1",clientId:"a",text:"Mój komentarz"}));await waitFor(()=>expect(screen.getByRole("textbox")).toBeEnabled());expect(screen.getAllByRole("listitem")).toHaveLength(1);expect(screen.getByRole("listitem")).not.toHaveTextContent("wysyłanie");expect(screen.getByRole("textbox")).toHaveValue("");expect(api.add).toHaveBeenCalledTimes(1);});
test("walidacja nie zapisuje, a kontrolowany draft przetrwa wynik błędu",async()=>{const api={add:vi.fn(),list:vi.fn(async()=>[])};render(<TrainingComments api={api}/>);await submit("a");expect(await screen.findByRole("alert")).toHaveTextContent("3–2000");expect(screen.getByRole("textbox")).toHaveValue("a");expect(screen.queryByRole("listitem")).toBeNull();expect(api.add).not.toHaveBeenCalled();});
test("jawnie odrzucony zapis sam usuwa warstwę, zachowując starsze dane",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[])};render(<TrainingComments api={api} initial={[{id:"old",clientId:"old",text:"Starszy"}]} makeId={()=>"a"}/>);await submit();expect(screen.getAllByRole("listitem")).toHaveLength(2);await act(async()=>task.reject(new MutationFailure("400","rejected")));expect(await screen.findByRole("alert")).toHaveTextContent("odrzucił");expect(screen.getAllByRole("listitem")).toHaveLength(1);expect(screen.getByRole("listitem")).toHaveTextContent("Starszy");expect(screen.getByRole("textbox")).toHaveValue("Mój komentarz");expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeEnabled();});
test("nieznany wynik blokuje POST, a odczyt odnajduje zapis",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[{id:"s1",clientId:"a",text:"Mój komentarz"}])};render(<TrainingComments api={api} makeId={()=>"a"}/>);await submit();await act(async()=>task.reject(Error("network")));expect(await screen.findByRole("alert")).toHaveTextContent("Nieznany wynik");expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeDisabled();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Sprawdź dane"})));await waitFor(()=>expect(screen.getByRole("textbox")).toHaveValue(""));expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeEnabled();expect(screen.getByRole("listitem")).toHaveTextContent("Mój komentarz");expect(api.add).toHaveBeenCalledTimes(1);});
test("po autorytatywnym odczycie braku zapisu retry zachowuje clientId",async()=>{let sequence=0;const first=deferred<Comment>(),second=deferred<Comment>(),api={add:vi.fn().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise),list:vi.fn(async()=>[])};render(<TrainingComments api={api} makeId={()=>"a"+(++sequence)}/>);await submit();await act(async()=>first.reject(Error("network")));await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Sprawdź dane"})));await waitFor(()=>expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeEnabled());await act(async()=>fireEvent.submit(screen.getByRole("form")));expect(api.add.mock.calls[0][0].clientId).toBe(api.add.mock.calls[1][0].clientId);await act(async()=>second.resolve({id:"s1",clientId:"a1",text:"Mój komentarz"}));});
test("drugi submit podczas oczekiwania nie kolejkuje nowego zapisu",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[])};render(<TrainingComments api={api} makeId={()=>"a"}/>);await submit();await act(async()=>fireEvent.submit(screen.getByRole("form")));expect(api.add).toHaveBeenCalledTimes(1);await act(async()=>task.resolve({id:"s1",clientId:"a",text:"Mój komentarz"}));expect(api.add).toHaveBeenCalledTimes(1);});
test("nieudane sprawdzenie pozostawia blokadę nieznanego zapisu",async()=>{const api={add:vi.fn(async()=>{throw Error("network");}),list:vi.fn(async()=>{throw Error("offline");})};render(<TrainingComments api={api}/>);await submit();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Sprawdź dane"})));expect(await screen.findByText("Nie udało się sprawdzić wyniku.")).toBeVisible();expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeDisabled();});
test("polubienie jest widoczne przed odpowiedzią, a porażka cofa tylko podgląd",async()=>{const task=deferred<boolean>();render(<LikeExercise saveAction={()=>task.promise}/>);await act(async()=>fireEvent.click(screen.getByRole("button")));expect(screen.getByRole("button")).toHaveAttribute("aria-pressed","true");expect(screen.getByRole("button")).toBeDisabled();await act(async()=>task.reject(Error("Odmowa")));expect(await screen.findByRole("alert")).toHaveTextContent("Nie potwierdzono");expect(screen.getByRole("button")).toHaveAttribute("aria-pressed","false");expect(screen.getByRole("button")).toBeEnabled();});
test("potwierdzone polubienie pozostaje po zakończeniu Action",async()=>{render(<LikeExercise saveAction={async value=>value}/>);await act(async()=>fireEvent.click(screen.getByRole("button")));expect(screen.getByRole("button")).toHaveAttribute("aria-pressed","true");expect(screen.getByRole("button")).toBeEnabled();});

import {StrictMode} from "react";import {act,fireEvent,render,screen,waitFor} from "@testing-library/react";import {expect,test,vi} from "vitest";import {Greeting,GreetingContext,UserExplorer} from "./UserExplorer";import {TrainingComments} from "./TrainingComments";import {LikeExercise} from "./LikeExercise";import {createUsers,deferred} from "./trainingModel";import {MutationFailure,type Comment} from "./commentModel";async function submit(text="Mój komentarz"){await act(async()=>{fireEvent.change(screen.getByRole("textbox",{name:"Nowy komentarz"}),{target:{value:text}});fireEvent.submit(screen.getByRole("form",{name:"Komentarze"}));});}
test("warunkowe use kontekstu można włączyć po renderze bez odczytu",()=>{const view=render(<Greeting enabled={false}/>);expect(screen.getByText("Powitanie wyłączone")).toBeVisible();view.rerender(<GreetingContext value="Cześć"><Greeting enabled/></GreetingContext>);expect(screen.getByText("Cześć")).toBeVisible();view.rerender(<Greeting enabled/>);expect(screen.getByText("Witaj")).toBeVisible();});
