test("po autorytatywnym odczycie braku zapisu retry zachowuje clientId",async()=>{let sequence=0;const first=deferred<Comment>(),second=deferred<Comment>(),api={add:vi.fn().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise),list:vi.fn(async()=>[])};render(<TrainingComments api={api} makeId={()=>"a"+(++sequence)}/>);await submit();await act(async()=>first.reject(Error("network")));await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Sprawdź dane"})));await waitFor(()=>expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeEnabled());await act(async()=>fireEvent.submit(screen.getByRole("form")));expect(api.add.mock.calls[0][0].clientId).toBe(api.add.mock.calls[1][0].clientId);await act(async()=>second.resolve({id:"s1",clientId:"a1",text:"Mój komentarz"}));});
test("drugi submit podczas oczekiwania nie kolejkuje nowego zapisu",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[])};render(<TrainingComments api={api} makeId={()=>"a"}/>);await submit();await act(async()=>fireEvent.submit(screen.getByRole("form")));expect(api.add).toHaveBeenCalledTimes(1);await act(async()=>task.resolve({id:"s1",clientId:"a",text:"Mój komentarz"}));expect(api.add).toHaveBeenCalledTimes(1);});
test("nieudane sprawdzenie pozostawia blokadę nieznanego zapisu",async()=>{const api={add:vi.fn(async()=>{throw Error("network");}),list:vi.fn(async()=>{throw Error("offline");})};render(<TrainingComments api={api}/>);await submit();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Sprawdź dane"})));expect(await screen.findByText("Nie udało się sprawdzić wyniku.")).toBeVisible();expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeDisabled();});
test("polubienie jest widoczne przed odpowiedzią, a porażka cofa tylko podgląd",async()=>{const task=deferred<boolean>();render(<LikeExercise saveAction={()=>task.promise}/>);await act(async()=>fireEvent.click(screen.getByRole("button")));expect(screen.getByRole("button")).toHaveAttribute("aria-pressed","true");expect(screen.getByRole("button")).toBeDisabled();await act(async()=>task.reject(Error("Odmowa")));expect(await screen.findByRole("alert")).toHaveTextContent("Nie potwierdzono");expect(screen.getByRole("button")).toHaveAttribute("aria-pressed","false");expect(screen.getByRole("button")).toBeEnabled();});
test("potwierdzone polubienie pozostaje po zakończeniu Action",async()=>{render(<LikeExercise saveAction={async value=>value}/>);await act(async()=>fireEvent.click(screen.getByRole("button")));expect(screen.getByRole("button")).toHaveAttribute("aria-pressed","true");expect(screen.getByRole("button")).toBeEnabled();});

